/* JY Game Kit v1.0.0 - shared runtime for every game on jyfk.lol
 *
 * DO NOT EDIT THIS FILE INSIDE A GAME FOLDER.
 * factory/verify_game.py checks that games/<slug>/kit/jy-kit.js is byte-identical
 * to the master copy in kit/jy-kit.js of the site repo.
 *
 * Full API reference: plan/_GAME-PROTOCOL.md in the HQ repo.
 */
export const KIT_VERSION = '1.0.0';

const FONT = 'system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif';
const STEP = 1 / 60;

/* ------------------------------------------------------------------ utils */
const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
const lerp = (a, b, t) => a + (b - a) * t;
const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);
const dist2 = (x1, y1, x2, y2) => (x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1);
const angleTo = (x1, y1, x2, y2) => Math.atan2(y2 - y1, x2 - x1);
const approach = (cur, target, delta) => (cur < target ? Math.min(cur + delta, target) : Math.max(cur - delta, target));
const wrap = (v, a, b) => { const r = b - a; return ((((v - a) % r) + r) % r) + a; };
const hsl = (h, s, l, a = 1) => `hsla(${h},${s}%,${l}%,${a})`;
const rectsOverlap = (a, b) => a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
const circleRect = (cx, cy, r, x, y, w, h) => {
  const nx = clamp(cx, x, x + w), ny = clamp(cy, y, y + h);
  return dist2(cx, cy, nx, ny) <= r * r;
};
const circlesOverlap = (x1, y1, r1, x2, y2, r2) => dist2(x1, y1, x2, y2) <= (r1 + r2) * (r1 + r2);
const ease = {
  linear: t => t,
  inQuad: t => t * t,
  outQuad: t => 1 - (1 - t) * (1 - t),
  inOutQuad: t => (t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2),
  outCubic: t => 1 - Math.pow(1 - t, 3),
  inOutSine: t => -(Math.cos(Math.PI * t) - 1) / 2,
  outBack: t => { const c1 = 1.70158, c3 = c1 + 1; return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2); },
  outElastic: t => (t === 0 || t === 1 ? t : Math.pow(2, -10 * t) * Math.sin((t * 10 - 0.75) * (2 * Math.PI / 3)) + 1),
};
const util = { clamp, lerp, dist, dist2, angleTo, approach, wrap, hsl, ease, rectsOverlap, circleRect, circlesOverlap };

function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function freshSeed() {
  try { const a = new Uint32Array(1); crypto.getRandomValues(a); return a[0] || 1; }
  catch (e) { return (Date.now() ^ 0x9e3779b9) >>> 0; }
}

/* ---------------------------------------------------------------- storage */
function makeStore(id) {
  const k = key => `jy:${id}:${key}`;
  return {
    load(key, def) {
      try { const v = localStorage.getItem(k(key)); return v === null ? def : JSON.parse(v); }
      catch (e) { return def; }
    },
    save(key, val) { try { localStorage.setItem(k(key), JSON.stringify(val)); } catch (e) { /* private mode */ } },
  };
}

/* ------------------------------------------------------------------ audio */
class Sound {
  constructor(store) {
    this.store = store;
    this.ctx = null;
    this.master = null;
    this.muted = !!store.load('muted', false);
    this.enabled = true;
  }
  unlock() {
    if (!this.ctx) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      try {
        this.ctx = new AC();
        this.master = this.ctx.createGain();
        this.master.gain.value = 0.45;
        this.master.connect(this.ctx.destination);
      } catch (e) { this.ctx = null; return; }
    }
    if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
  }
  get ready() { return this.enabled && !this.muted && this.ctx && this.ctx.state === 'running'; }
  setMuted(m) { this.muted = !!m; this.store.save('muted', this.muted); }
  tone(freq = 440, dur = 0.1, type = 'sine', vol = 0.25, slide = 0, delay = 0) {
    if (!this.ready) return;
    try {
      const c = this.ctx, t = c.currentTime + Math.max(0, delay);
      const o = c.createOscillator(), g = c.createGain();
      o.type = type;
      o.frequency.setValueAtTime(Math.max(20, freq), t);
      if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + dur);
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(Math.max(0.0002, vol), t + 0.008);
      g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      o.connect(g); g.connect(this.master);
      o.start(t); o.stop(t + dur + 0.03);
    } catch (e) { /* ignore audio errors */ }
  }
  noise(dur = 0.2, vol = 0.25, delay = 0, freq = 1200) {
    if (!this.ready) return;
    try {
      const c = this.ctx, t = c.currentTime + Math.max(0, delay);
      const len = Math.max(1, Math.floor(c.sampleRate * dur));
      const buf = c.createBuffer(1, len, c.sampleRate);
      const d = buf.getChannelData(0);
      let s = 12345;
      for (let i = 0; i < len; i++) { s = (s * 1103515245 + 12345) & 0x7fffffff; d[i] = (s / 0x3fffffff - 1) * (1 - i / len); }
      const src = c.createBufferSource(); src.buffer = buf;
      const f = c.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = freq;
      const g = c.createGain(); g.gain.value = vol;
      src.connect(f); f.connect(g); g.connect(this.master);
      src.start(t);
    } catch (e) { /* ignore */ }
  }
  sfx(name) {
    switch (name) {
      case 'click': this.tone(700, 0.05, 'square', 0.12); break;
      case 'select': this.tone(520, 0.06, 'triangle', 0.2); this.tone(780, 0.08, 'triangle', 0.18, 0, 0.05); break;
      case 'coin': this.tone(988, 0.07, 'square', 0.16); this.tone(1319, 0.12, 'square', 0.16, 0, 0.06); break;
      case 'pop': this.tone(420, 0.07, 'sine', 0.3, 520); break;
      case 'jump': this.tone(280, 0.16, 'square', 0.16, 340); break;
      case 'shoot': this.tone(900, 0.08, 'sawtooth', 0.1, -600); break;
      case 'hit': this.noise(0.14, 0.3, 0, 900); this.tone(180, 0.14, 'sawtooth', 0.18, -110); break;
      case 'explode': this.noise(0.5, 0.45, 0, 700); this.tone(110, 0.4, 'sawtooth', 0.15, -70); break;
      case 'powerup': [0, 0.06, 0.12, 0.18].forEach((d, i) => this.tone(523 * Math.pow(1.26, i), 0.09, 'triangle', 0.18, 0, d)); break;
      case 'win': [0, 0.1, 0.2, 0.32].forEach((d, i) => this.tone([523, 659, 784, 1047][i], 0.16, 'triangle', 0.2, 0, d)); break;
      case 'lose': [0, 0.14, 0.28].forEach((d, i) => this.tone([392, 330, 262][i], 0.2, 'triangle', 0.2, 0, d)); break;
      case 'tick': this.tone(1400, 0.03, 'square', 0.06); break;
      case 'whoosh': this.noise(0.22, 0.16, 0, 2500); break;
      case 'error': this.tone(160, 0.18, 'square', 0.14); break;
      case 'combo': this.tone(660, 0.06, 'square', 0.14); this.tone(990, 0.09, 'square', 0.14, 0, 0.05); break;
      default: this.tone(440, 0.08, 'sine', 0.15);
    }
  }
}

/* ------------------------------------------------------------------ input */
class Input {
  constructor(actions) {
    this.actions = actions || {};
    this.names = Object.keys(this.actions);
    this.byCode = {};
    for (const [act, codes] of Object.entries(this.actions)) {
      for (const c of codes || []) (this.byCode[c] = this.byCode[c] || []).push(act);
    }
    this.raw = {};      // keyboard
    this.touch = {};    // on-screen buttons
    this.virt = {};     // bot, this tick only
    this.qPress = new Set();
    this.qRelease = new Set();
    this.cur = {}; this.prev = {}; this.pMap = {}; this.rMap = {};
  }
  keydown(code) {
    const acts = this.byCode[code];
    if (!acts) return false;
    for (const a of acts) { if (!this.raw[a]) this.qPress.add(a); this.raw[a] = true; }
    return true;
  }
  keyup(code) {
    const acts = this.byCode[code];
    if (!acts) return false;
    for (const a of acts) { if (this.raw[a]) this.qRelease.add(a); this.raw[a] = false; }
    return true;
  }
  setTouch(act, v) {
    if (v && !this.touch[act]) this.qPress.add(act);
    if (!v && this.touch[act]) this.qRelease.add(act);
    this.touch[act] = !!v;
  }
  clearAll() { this.raw = {}; this.touch = {}; this.virt = {}; this.qPress.clear(); this.qRelease.clear(); this.cur = {}; this.prev = {}; this.pMap = {}; this.rMap = {}; }
  // game-facing
  down(a) { return !!this.cur[a]; }
  pressed(a) { return !!this.pMap[a]; }
  released(a) { return !!this.rMap[a]; }
  // bot-facing (valid for the next tick only; call every tick while holding)
  hold(a) { this.virt[a] = true; }
  tap(a) { this.virt[a] = true; }
  _begin() {
    for (const a of this.names) {
      const c = !!(this.raw[a] || this.touch[a] || this.virt[a]);
      this.cur[a] = c;
      this.pMap[a] = (c && !this.prev[a]) || this.qPress.has(a);
      this.rMap[a] = (!c && !!this.prev[a]) || this.qRelease.has(a);
    }
  }
  _end() {
    for (const a of this.names) this.prev[a] = this.cur[a];
    this.virt = {};
    this.qPress.clear(); this.qRelease.clear();
  }
}

class Pointer {
  constructor() {
    this.reads = 0;
    this.real = { x: 0, y: 0, down: false };
    this.q = { pressed: false, released: false, swipe: null };
    this.virt = null;
    this.s = { x: 0, y: 0, down: false, pressed: false, released: false, swipe: null };
    this.prevDown = false;
  }
  get x() { this.reads++; return this.s.x; }
  get y() { this.reads++; return this.s.y; }
  get down() { this.reads++; return this.s.down; }
  get pressed() { this.reads++; return this.s.pressed; }
  get released() { this.reads++; return this.s.released; }
  get swipe() { this.reads++; return this.s.swipe; }
  // bot-facing (next tick only)
  set(x, y, down) { this.virt = { x, y, down: !!down, swipe: this.virt ? this.virt.swipe : null }; }
  swipeTo(dir) { const b = this.virt || { x: this.real.x, y: this.real.y, down: false }; this.virt = { ...b, swipe: dir }; }
  clearAll() { this.real.down = false; this.q = { pressed: false, released: false, swipe: null }; this.virt = null; this.prevDown = false; this.s = { x: this.real.x, y: this.real.y, down: false, pressed: false, released: false, swipe: null }; }
  _begin() {
    const src = this.virt || this.real;
    const down = !!src.down;
    const pressed = (down && !this.prevDown) || (!this.virt && this.q.pressed);
    const released = (!down && this.prevDown) || (!this.virt && this.q.released);
    this.s = { x: src.x, y: src.y, down, pressed, released, swipe: this.virt ? (this.virt.swipe || null) : this.q.swipe };
  }
  _end() {
    this.prevDown = this.s.down;
    this.q.pressed = false; this.q.released = false; this.q.swipe = null;
    this.virt = null;
  }
}

/* -------------------------------------------------------------------- css */
const CSS = `
#jy-root{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;background:var(--jy-letterbox,#05070d);overflow:hidden;touch-action:none;user-select:none;-webkit-user-select:none;-webkit-tap-highlight-color:transparent;font-family:${FONT};}
#jy-frame{position:relative;overflow:hidden;flex:none;}
#jy-canvas{display:block;width:100%;height:100%;touch-action:none;}
.jy-ov{position:absolute;inset:0;display:none;flex-direction:column;align-items:center;justify-content:center;gap:.55em;text-align:center;color:#fff;background:rgba(6,9,22,.64);padding:1.4em;box-sizing:border-box;z-index:6;}
.jy-ov.on{display:flex;}
.jy-ov h1{font-size:2.15em;margin:0 0 .15em;line-height:1.08;text-shadow:0 4px 18px rgba(0,0,0,.55);letter-spacing:.01em;}
.jy-ov h2{font-size:1.85em;margin:0;line-height:1.1;}
.jy-ov p{margin:0;font-size:1em;line-height:1.35;opacity:.94;max-width:21em;}
.jy-ov .jy-small{font-size:.8em;opacity:.75;}
.jy-btn{font:inherit;font-size:1.15em;font-weight:800;border:0;border-radius:999px;padding:.68em 2.1em;background:var(--jy-accent,#ffd23f);color:#1d1600;cursor:pointer;box-shadow:0 .3em 0 rgba(0,0,0,.28);margin-top:.35em;}
.jy-btn:active{transform:translateY(.15em);box-shadow:0 .15em 0 rgba(0,0,0,.28);}
.jy-btn[disabled]{opacity:.45;cursor:default;}
.jy-score{font-size:1.7em;font-weight:800;}
.jy-newbest{color:var(--jy-accent,#ffd23f);font-weight:800;display:none;}
.jy-hb{position:absolute;top:.45em;right:.45em;display:flex;gap:.4em;z-index:7;}
.jy-ib{width:2.3em;height:2.3em;border-radius:50%;border:0;background:rgba(0,0,0,.38);color:#fff;display:flex;align-items:center;justify-content:center;cursor:pointer;padding:0;}
.jy-ib svg{width:52%;height:52%;fill:currentColor;}
.jy-tb{position:absolute;box-sizing:border-box;border-radius:50%;background:rgba(255,255,255,.13);border:.12em solid rgba(255,255,255,.38);color:#fff;font-weight:800;display:flex;align-items:center;justify-content:center;touch-action:none;z-index:5;transform:translate(-50%,-50%);}
.jy-tb.on{background:rgba(255,255,255,.34);}
`;
const ICON_PAUSE = '<svg viewBox="0 0 24 24"><rect x="5" y="4" width="5" height="16" rx="1"/><rect x="14" y="4" width="5" height="16" rx="1"/></svg>';
const ICON_SOUND = '<svg viewBox="0 0 24 24"><path d="M4 9h4l5-4v14l-5-4H4z"/><path d="M16 8.5a5 5 0 0 1 0 7" stroke="currentColor" stroke-width="2" fill="none"/><path d="M18.5 6a8.5 8.5 0 0 1 0 12" stroke="currentColor" stroke-width="2" fill="none"/></svg>';
const ICON_MUTE = '<svg viewBox="0 0 24 24"><path d="M4 9h4l5-4v14l-5-4H4z"/><path d="M16 9l5 6M21 9l-5 6" stroke="currentColor" stroke-width="2"/></svg>';

function esc(s) { return String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); }

/* ------------------------------------------------------------- createGame */
export function createGame(def) {
  const required = ['id', 'title', 'reset', 'update', 'render', 'bot', 'drawCover'];
  for (const k of required) {
    if (!def || def[k] === undefined) throw new Error(`[JY kit] game definition is missing "${k}"`);
  }
  for (const k of ['reset', 'update', 'render', 'bot', 'drawCover']) {
    if (typeof def[k] !== 'function') throw new Error(`[JY kit] "${k}" must be a function`);
  }
  const orientation = def.orientation === 'landscape' ? 'landscape' : 'portrait';
  const W = def.width || (orientation === 'portrait' ? 720 : 1280);
  const H = def.height || (orientation === 'portrait' ? 1280 : 720);

  const store = makeStore(def.id);
  const sound = new Sound(store);
  const input = new Input(def.actions || {});
  const pointer = new Pointer();
  const errors = [];

  let state = 'boot';
  let score = 0;
  let best = Number(store.load('best', 0)) || 0;
  let time = 0, frame = 0, frames = 0;
  let rng = mulberry32(1), fxRng = mulberry32(7);
  let fixedSeed = null;
  let timers = [];
  let particles = [], texts = [];
  let shake = { t: 0, d: 0, m: 0, x: 0, y: 0 };
  let flash = { t: 0, d: 0, color: '#fff' };
  let autopilot = false, testBusy = false;
  let overAt = 0;

  /* ---------- DOM ---------- */
  const style = document.createElement('style');
  style.textContent = CSS;
  document.head.appendChild(style);
  let root = document.getElementById('jy-root');
  if (!root) { root = document.createElement('div'); root.id = 'jy-root'; document.body.appendChild(root); }
  if (def.letterbox) root.style.setProperty('--jy-letterbox', def.letterbox);
  if (def.accent) root.style.setProperty('--jy-accent', def.accent);
  const frameEl = document.createElement('div'); frameEl.id = 'jy-frame';
  const canvas = document.createElement('canvas'); canvas.id = 'jy-canvas';
  frameEl.appendChild(canvas);
  root.appendChild(frameEl);
  const ctx = canvas.getContext('2d');

  const hb = document.createElement('div'); hb.className = 'jy-hb';
  const btnPause = document.createElement('button'); btnPause.className = 'jy-ib'; btnPause.id = 'jy-btn-pause'; btnPause.setAttribute('aria-label', 'Pause'); btnPause.innerHTML = ICON_PAUSE;
  const btnMute = document.createElement('button'); btnMute.className = 'jy-ib'; btnMute.id = 'jy-btn-mute'; btnMute.setAttribute('aria-label', 'Sound');
  hb.appendChild(btnPause); hb.appendChild(btnMute);
  frameEl.appendChild(hb);

  const ovTitle = document.createElement('div'); ovTitle.className = 'jy-ov'; ovTitle.id = 'jy-title';
  ovTitle.innerHTML = `<h1>${esc(def.title)}</h1>${def.howTo ? `<p>${esc(def.howTo)}</p>` : ''}<button class="jy-btn" id="jy-play">Play</button><p class="jy-small jy-best-line"></p>`;
  const ovPause = document.createElement('div'); ovPause.className = 'jy-ov'; ovPause.id = 'jy-pause';
  ovPause.innerHTML = `<h2>Paused</h2><button class="jy-btn" id="jy-resume">Resume</button><p class="jy-small">Press P or Esc to resume</p>`;
  const ovOver = document.createElement('div'); ovOver.className = 'jy-ov'; ovOver.id = 'jy-over';
  ovOver.innerHTML = `<h2>${esc(def.overTitle || 'Game Over')}</h2><p class="jy-score"></p><p class="jy-newbest">New best!</p><p class="jy-best-line"></p><button class="jy-btn" id="jy-again">Play again</button>`;
  frameEl.appendChild(ovTitle); frameEl.appendChild(ovPause); frameEl.appendChild(ovOver);

  const isTouch = (() => { try { return matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window; } catch (e) { return false; } })();
  const touchEls = [];
  if (isTouch && Array.isArray(def.touchButtons)) {
    for (const b of def.touchButtons) {
      const el = document.createElement('div');
      el.className = 'jy-tb';
      el.textContent = b.label || '';
      el.dataset.action = b.action;
      const size = b.size || 0.17;
      el.style.left = `${(b.x !== undefined ? b.x : 0.5) * 100}%`;
      el.style.top = `${(b.y !== undefined ? b.y : 0.88) * 100}%`;
      el._size = size;
      const on = e => { e.preventDefault(); sound.unlock(); input.setTouch(b.action, true); el.classList.add('on'); try { el.setPointerCapture(e.pointerId); } catch (_) {} };
      const off = e => { e.preventDefault(); input.setTouch(b.action, false); el.classList.remove('on'); };
      el.addEventListener('pointerdown', on);
      el.addEventListener('pointerup', off);
      el.addEventListener('pointercancel', off);
      el.addEventListener('lostpointercapture', off);
      frameEl.appendChild(el);
      touchEls.push(el);
    }
  }

  function updateMuteIcon() { btnMute.innerHTML = sound.muted ? ICON_MUTE : ICON_SOUND; }
  updateMuteIcon();

  /* ---------- layout ---------- */
  let cssW = W, cssH = H, dpr = 1;
  function layout() {
    const aw = root.clientWidth || window.innerWidth || W;
    const ah = root.clientHeight || window.innerHeight || H;
    const s = Math.min(aw / W, ah / H);
    cssW = Math.max(1, Math.floor(W * s));
    cssH = Math.max(1, Math.floor(H * s));
    dpr = Math.min(2, window.devicePixelRatio || 1);
    frameEl.style.width = cssW + 'px';
    frameEl.style.height = cssH + 'px';
    canvas.width = Math.max(1, Math.round(cssW * dpr));
    canvas.height = Math.max(1, Math.round(cssH * dpr));
    frameEl.style.fontSize = Math.max(11, Math.min(30, cssW / 21)) + 'px';
    for (const el of touchEls) {
      const px = el._size * cssW;
      el.style.width = px + 'px'; el.style.height = px + 'px'; el.style.fontSize = (px * 0.42) + 'px';
    }
    safeDraw();
  }
  window.addEventListener('resize', layout);
  window.addEventListener('orientationchange', () => setTimeout(layout, 120));

  /* ---------- api ---------- */
  const api = {
    W, H, dt: STEP, isTouch, util,
    input, pointer,
    get time() { return time; },
    get frame() { return frame; },
    get state() { return state; },
    get score() { return score; },
    set score(v) { score = Number(v) || 0; },
    get best() { return best; },
    g: ctx,
    rand: () => rng(),
    randRange: (a, b) => a + (b - a) * rng(),
    randInt: (a, b) => Math.floor(a + (b - a + 1) * rng()),
    chance: p => rng() < p,
    pick: arr => arr[Math.floor(rng() * arr.length)],
    shuffle(arr) { for (let i = arr.length - 1; i > 0; i--) { const j = Math.floor(rng() * (i + 1)); const t = arr[i]; arr[i] = arr[j]; arr[j] = t; } return arr; },
    addScore(n, x, y, color) {
      score += n;
      if (x !== undefined && y !== undefined) api.floatText(x, y, (n >= 0 ? '+' : '') + n, color || '#fff');
    },
    gameOver() { gameOver(); },
    after(sec, fn) { timers.push({ at: time + Math.max(0, sec), fn }); },
    sfx: name => sound.sfx(name),
    tone: (f, d, t, v, s, delay) => sound.tone(f, d, t, v, s, delay),
    noise: (d, v, delay, f) => sound.noise(d, v, delay, f),
    vibrate(ms) { try { if (navigator.vibrate && !testBusy) navigator.vibrate(ms); } catch (e) { /* ignore */ } },
    shake(m = 10, d = 0.25) { if (m >= shake.m || shake.t <= 0) { shake.m = m; shake.d = d; shake.t = d; } },
    flash(color = '#ffffff', d = 0.15) { flash.color = color; flash.d = d; flash.t = d; },
    burst(x, y, o = {}) {
      const n = Math.min(80, o.count === undefined ? 14 : o.count);
      for (let i = 0; i < n && particles.length < 500; i++) {
        const ang = (o.angle !== undefined ? o.angle : 0) + (fxRng() - 0.5) * (o.spread !== undefined ? o.spread : Math.PI * 2);
        const sp = (o.speed !== undefined ? o.speed : 260) * (0.35 + fxRng() * 0.65);
        const life = (o.life !== undefined ? o.life : 0.6) * (0.6 + fxRng() * 0.4);
        const colors = Array.isArray(o.color) ? o.color : [o.color || '#ffffff'];
        particles.push({ x, y, vx: Math.cos(ang) * sp, vy: Math.sin(ang) * sp, life, max: life, size: (o.size || 5) * (0.6 + fxRng() * 0.6), color: colors[Math.floor(fxRng() * colors.length)], g: o.gravity || 0, drag: o.drag !== undefined ? o.drag : 1.5, shape: o.shape || 'circle' });
      }
    },
    floatText(x, y, str, color = '#fff', size = 40) { if (texts.length < 60) texts.push({ x, y, str: String(str), color, size, life: 0.9, max: 0.9 }); },
    save: (k, v) => store.save('d:' + k, v),
    load: (k, d) => store.load('d:' + k, d),
    text(str, x, y, o = {}) {
      const g = api.g;
      g.save();
      g.globalAlpha *= (o.alpha === undefined ? 1 : o.alpha);
      g.font = `${o.weight || 700} ${o.size || 32}px ${o.font || FONT}`;
      g.textAlign = o.align || 'center';
      g.textBaseline = o.baseline || 'middle';
      if (o.shadow) { g.shadowColor = o.shadow; g.shadowBlur = o.shadowBlur || 12; }
      if (o.stroke) { g.lineJoin = 'round'; g.lineWidth = o.strokeWidth || 6; g.strokeStyle = o.stroke; g.strokeText(String(str), x, y, o.maxWidth); }
      g.fillStyle = o.color || '#fff';
      g.fillText(String(str), x, y, o.maxWidth);
      g.restore();
    },
    circle(x, y, r, fill, stroke, lw = 3) {
      const g = api.g; g.beginPath(); g.arc(x, y, Math.max(0, r), 0, Math.PI * 2);
      if (fill) { g.fillStyle = fill; g.fill(); }
      if (stroke) { g.lineWidth = lw; g.strokeStyle = stroke; g.stroke(); }
    },
    rect(x, y, w, h, fill, stroke, lw = 3) {
      const g = api.g;
      if (fill) { g.fillStyle = fill; g.fillRect(x, y, w, h); }
      if (stroke) { g.lineWidth = lw; g.strokeStyle = stroke; g.strokeRect(x, y, w, h); }
    },
    roundRect(x, y, w, h, r, fill, stroke, lw = 3) {
      const g = api.g; const rr = Math.max(0, Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2));
      g.beginPath();
      g.moveTo(x + rr, y); g.lineTo(x + w - rr, y); g.quadraticCurveTo(x + w, y, x + w, y + rr);
      g.lineTo(x + w, y + h - rr); g.quadraticCurveTo(x + w, y + h, x + w - rr, y + h);
      g.lineTo(x + rr, y + h); g.quadraticCurveTo(x, y + h, x, y + h - rr);
      g.lineTo(x, y + rr); g.quadraticCurveTo(x, y, x + rr, y); g.closePath();
      if (fill) { g.fillStyle = fill; g.fill(); }
      if (stroke) { g.lineWidth = lw; g.strokeStyle = stroke; g.stroke(); }
    },
    line(x1, y1, x2, y2, color = '#fff', lw = 3) {
      const g = api.g; g.beginPath(); g.moveTo(x1, y1); g.lineTo(x2, y2); g.lineWidth = lw; g.strokeStyle = color; g.lineCap = 'round'; g.stroke();
    },
    poly(points, fill, stroke, lw = 3) {
      if (!points || points.length < 2) return;
      const g = api.g; g.beginPath(); g.moveTo(points[0][0], points[0][1]);
      for (let i = 1; i < points.length; i++) g.lineTo(points[i][0], points[i][1]);
      g.closePath();
      if (fill) { g.fillStyle = fill; g.fill(); }
      if (stroke) { g.lineWidth = lw; g.strokeStyle = stroke; g.stroke(); }
    },
  };

  /* ---------- errors ---------- */
  function reportError(where, e) {
    errors.push(`${where}: ${e && e.stack ? e.stack : e}`);
    if (errors.length <= 5) console.error(`[JY kit] error in ${where}:`, e);
  }

  /* ---------- state machine ---------- */
  function seedRun(seed) {
    const s = (seed !== undefined && seed !== null) ? seed : (fixedSeed !== null ? fixedSeed : freshSeed());
    rng = mulberry32(s);
    fxRng = mulberry32((s ^ 0x5bd1e995) >>> 0);
  }
  function resetRun(seed) {
    seedRun(seed);
    score = 0; time = 0; frame = 0;
    timers = []; particles = []; texts = [];
    shake = { t: 0, d: 0, m: 0, x: 0, y: 0 }; flash = { t: 0, d: 0, color: '#fff' };
    input.clearAll(); pointer.clearAll();
    try { def.reset(api); } catch (e) { reportError('reset', e); }
  }
  function start(seed) {
    sound.unlock();
    resetRun(seed);
    state = 'playing';
    updateOverlays();
  }
  function gameOver() {
    if (state !== 'playing') return;
    state = 'over';
    if (!Number.isFinite(score)) { reportError('score', new Error('score is not a finite number')); score = 0; }
    const isBest = score > best;
    if (isBest) { best = score; store.save('best', best); }
    ovOver.querySelector('.jy-newbest').style.display = isBest && score > 0 ? 'block' : 'none';
    overAt = performance.now();
    updateOverlays();
    const again = ovOver.querySelector('#jy-again');
    if (!testBusy) { again.disabled = true; setTimeout(() => { again.disabled = false; }, 450); }
  }
  function pause() { if (state === 'playing') { state = 'paused'; input.clearAll(); pointer.clearAll(); updateOverlays(); } }
  function resume() { if (state === 'paused') { state = 'playing'; last = 0; updateOverlays(); } }

  function updateOverlays() {
    ovTitle.classList.toggle('on', state === 'title');
    ovPause.classList.toggle('on', state === 'paused');
    ovOver.classList.toggle('on', state === 'over');
    btnPause.style.display = state === 'playing' ? 'flex' : 'none';
    for (const el of touchEls) el.style.display = state === 'playing' ? 'flex' : 'none';
    const bestTxt = best > 0 ? `Best: ${Math.floor(best)}` : '';
    for (const el of frameEl.querySelectorAll('.jy-best-line')) el.textContent = bestTxt;
    ovOver.querySelector('.jy-score').textContent = `Score: ${Math.floor(score)}`;
  }

  /* ---------- tick / render ---------- */
  function runTimers() {
    if (!timers.length) return;
    const due = timers.filter(t => t.at <= time);
    if (!due.length) return;
    timers = timers.filter(t => t.at > time);
    for (const t of due) { try { t.fn(api); } catch (e) { reportError('after()', e); } }
  }
  function fxUpdate(dt) {
    for (const p of particles) {
      p.life -= dt;
      p.vy += p.g * dt;
      const k = Math.max(0, 1 - p.drag * dt);
      p.vx *= k; p.vy *= k;
      p.x += p.vx * dt; p.y += p.vy * dt;
    }
    if (particles.length) particles = particles.filter(p => p.life > 0);
    for (const t of texts) { t.life -= dt; t.y -= 70 * dt; }
    if (texts.length) texts = texts.filter(t => t.life > 0);
    if (shake.t > 0) {
      shake.t -= dt;
      const k = Math.max(0, shake.t / (shake.d || 1));
      shake.x = (fxRng() * 2 - 1) * shake.m * k;
      shake.y = (fxRng() * 2 - 1) * shake.m * k;
      if (shake.t <= 0) { shake.x = 0; shake.y = 0; shake.m = 0; }
    }
    if (flash.t > 0) flash.t -= dt;
  }
  function tick(useBot) {
    try {
      if (useBot) def.bot(api);
      input._begin(); pointer._begin();
      def.update(STEP, api);
      runTimers();
      fxUpdate(STEP);
      if (!Number.isFinite(score)) { reportError('score', new Error('score became NaN/Infinity')); score = 0; }
    } catch (e) {
      reportError('update', e);
    }
    input._end(); pointer._end();
    time += STEP; frame++;
  }
  function drawFx(g) {
    for (const p of particles) {
      const a = Math.max(0, p.life / p.max);
      g.globalAlpha = a;
      g.fillStyle = p.color;
      const s = p.size * (0.4 + 0.6 * a);
      if (p.shape === 'square') g.fillRect(p.x - s, p.y - s, s * 2, s * 2);
      else { g.beginPath(); g.arc(p.x, p.y, s, 0, Math.PI * 2); g.fill(); }
    }
    g.globalAlpha = 1;
    for (const t of texts) {
      const a = Math.max(0, t.life / t.max);
      g.save();
      g.globalAlpha = a;
      g.font = `800 ${t.size}px ${FONT}`;
      g.textAlign = 'center'; g.textBaseline = 'middle';
      g.lineWidth = 6; g.strokeStyle = 'rgba(0,0,0,.55)'; g.lineJoin = 'round';
      g.strokeText(t.str, t.x, t.y);
      g.fillStyle = t.color; g.fillText(t.str, t.x, t.y);
      g.restore();
    }
  }
  function drawHud(g) {
    g.save();
    g.font = `800 ${def.hudSize || 56}px ${FONT}`;
    g.textAlign = 'center'; g.textBaseline = 'top';
    g.lineWidth = 8; g.lineJoin = 'round'; g.strokeStyle = 'rgba(0,0,0,.45)';
    const s = String(Math.floor(score));
    g.strokeText(s, W / 2, 26);
    g.fillStyle = def.hudColor || '#ffffff';
    g.fillText(s, W / 2, 26);
    g.restore();
  }
  function draw() {
    const g = ctx;
    g.setTransform(canvas.width / W, 0, 0, canvas.height / H, 0, 0);
    g.globalAlpha = 1; g.globalCompositeOperation = 'source-over';
    g.fillStyle = def.background || '#0b1020';
    g.fillRect(0, 0, W, H);
    g.save();
    if (shake.t > 0) g.translate(shake.x, shake.y);
    api.g = g;
    def.render(g, api);
    g.globalAlpha = 1; g.globalCompositeOperation = 'source-over';
    drawFx(g);
    g.restore();
    if (def.hud !== false && (state === 'playing' || state === 'paused')) drawHud(g);
    if (flash.t > 0) { g.save(); g.globalAlpha = Math.max(0, flash.t / (flash.d || 1)) * 0.55; g.fillStyle = flash.color; g.fillRect(0, 0, W, H); g.restore(); }
    frames++;
  }
  let renderErrors = 0;
  function safeDraw() {
    try { draw(); }
    catch (e) { renderErrors++; reportError('render', e); }
  }

  let last = 0, acc = 0;
  function loop(ts) {
    requestAnimationFrame(loop);
    if (testBusy) return;
    if (!last) last = ts;
    let dt = (ts - last) / 1000;
    last = ts;
    if (dt > 0.25) dt = 0.25;
    if (dt < 0) dt = 0;
    if (state === 'playing') {
      acc += dt;
      let n = 0;
      while (acc >= STEP && n < 8 && state === 'playing') { tick(autopilot); acc -= STEP; n++; }
      if (n >= 8) acc = 0;
    } else {
      fxUpdate(dt);
    }
    safeDraw();
  }

  /* ---------- events ---------- */
  function toLogical(e) {
    const r = canvas.getBoundingClientRect();
    return { x: ((e.clientX - r.left) / (r.width || 1)) * W, y: ((e.clientY - r.top) / (r.height || 1)) * H };
  }
  let swipeStart = null;
  canvas.addEventListener('pointerdown', e => {
    e.preventDefault();
    sound.unlock();
    try { window.focus(); } catch (_) {}
    try { canvas.setPointerCapture(e.pointerId); } catch (_) {}
    const p = toLogical(e);
    pointer.real.x = p.x; pointer.real.y = p.y; pointer.real.down = true; pointer.q.pressed = true;
    swipeStart = { x: p.x, y: p.y, t: performance.now() };
  });
  canvas.addEventListener('pointermove', e => {
    const p = toLogical(e);
    pointer.real.x = p.x; pointer.real.y = p.y;
  });
  const up = e => {
    const p = toLogical(e);
    pointer.real.x = p.x; pointer.real.y = p.y;
    if (pointer.real.down) pointer.q.released = true;
    pointer.real.down = false;
    if (swipeStart) {
      const dx = p.x - swipeStart.x, dy = p.y - swipeStart.y;
      const minD = Math.min(W, H) * 0.06;
      if (performance.now() - swipeStart.t < 650 && Math.hypot(dx, dy) > minD) {
        pointer.q.swipe = Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? 'right' : 'left') : (dy > 0 ? 'down' : 'up');
      }
      swipeStart = null;
    }
  };
  canvas.addEventListener('pointerup', up);
  canvas.addEventListener('pointercancel', up);
  canvas.addEventListener('contextmenu', e => e.preventDefault());

  const START_KEYS = new Set(['Space', 'Enter', 'NumpadEnter']);
  window.addEventListener('keydown', e => {
    const code = e.code;
    if (code === 'Space' || code.startsWith('Arrow') || input.byCode[code]) e.preventDefault();
    if (e.repeat) return;
    if ((code === 'KeyP' || code === 'Escape') && (state === 'playing' || state === 'paused')) {
      if (state === 'playing') pause(); else resume();
      return;
    }
    if (state === 'title' && START_KEYS.has(code)) { start(); return; }
    if (state === 'over' && START_KEYS.has(code)) {
      if (performance.now() - overAt > 450) start();
      return;
    }
    if (state === 'paused' && START_KEYS.has(code)) { resume(); return; }
    if (state === 'playing') { sound.unlock(); input.keydown(code); }
  });
  window.addEventListener('keyup', e => { input.keyup(e.code); });
  window.addEventListener('blur', () => { if (!testBusy) pause(); });
  document.addEventListener('visibilitychange', () => { if (document.hidden && !testBusy) pause(); });

  ovTitle.addEventListener('pointerdown', e => { e.preventDefault(); start(); });
  ovOver.querySelector('#jy-again').addEventListener('click', e => { e.stopPropagation(); start(); });
  ovPause.querySelector('#jy-resume').addEventListener('click', e => { e.stopPropagation(); resume(); });
  btnPause.addEventListener('click', e => { e.stopPropagation(); pause(); });
  btnMute.addEventListener('click', e => { e.stopPropagation(); sound.unlock(); sound.setMuted(!sound.muted); updateMuteIcon(); });

  /* ---------- test + automation hooks ---------- */
  window.JY = {
    version: KIT_VERSION,
    id: def.id,
    ready: false,
    state: () => state,
    score: () => score,
    best: () => best,
    start: seed => start(seed),
    restart: seed => start(seed),
    pause, resume,
    gameOver: () => gameOver(),
    test: {
      seed(n) { fixedSeed = n; },
      autopilot(on) { autopilot = !!on; },
      errors: () => errors.slice(),
      frames: () => frames,
      info: () => ({ W, H, orientation, actions: Object.keys(def.actions || {}), touchButtons: (def.touchButtons || []).length, isTouch, pointerReads: pointer.reads, kit: KIT_VERSION }),
      run(opts = {}) {
        const seconds = opts.seconds || 60;
        let seed = opts.seed || 12345;
        const restartOnOver = opts.restartOnOver !== false;
        const renderEvery = opts.renderEvery || 20;
        testBusy = true;
        sound.enabled = false;
        const errStart = errors.length;
        const runs = [];
        let maxScore = 0, ticks = 0, recorded = false;
        start(seed);
        const total = Math.round(seconds * 60);
        for (let i = 0; i < total; i++) {
          if (state === 'over') {
            runs.push(score); recorded = true;
            if (!restartOnOver) break;
            start(++seed); recorded = false;
          }
          if (state !== 'playing') break;
          tick(true);
          ticks++;
          if (score > maxScore) maxScore = score;
          if (i % renderEvery === 0) safeDraw();
          if (errors.length - errStart > 20) break;
        }
        if (!recorded) runs.push(score);
        safeDraw();
        sound.enabled = true;
        testBusy = false;
        last = 0;
        updateOverlays();
        return { ticks, runs, maxScore, finalState: state, newErrors: errors.slice(errStart), pointerReads: pointer.reads };
      },
      cover(w = 640, h = 360) {
        const c = document.createElement('canvas');
        c.width = w; c.height = h;
        const g = c.getContext('2d');
        const prev = api.g;
        api.g = g;
        try { def.drawCover(g, w, h, api); } catch (e) { reportError('drawCover', e); }
        api.g = prev;
        return c.toDataURL('image/png');
      },
    },
  };

  /* ---------- boot ---------- */
  try { if (typeof def.init === 'function') { seedRun(); def.init(api); } }
  catch (e) { reportError('init', e); }
  resetRun();
  state = 'title';
  layout();
  updateOverlays();
  requestAnimationFrame(loop);
  window.JY.ready = true;
  return api;
}
